import { profile } from '../data/profile.js';
import { projects } from '../data/projects.js';
import { skills } from '../data/skills.js';
import { github } from '../data/github.js';
import { achievements } from '../data/achievements.js';
import { semesters, suppliedCgpa } from '../data/academics/semesters.js';
import { subjects } from '../data/academics/subjects.js';
import { academicMetrics, gpaSeries, semesterSubjects, standoutSubjects } from '../utils/academics/analytics.js';
import { renderGpaChart } from './academic-chart.js';
import { renderAcademicView } from './academic-view.js';
import { renderLeetCodeView } from './leetcode-view.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(id,label)=>`<button class="text-button" data-open="${id}">${label}</button>`;
export function renderContent(id,win){return ({about:aboutView,thispc:pcView,academics:academicView,projects:projectsView,skills:skillsView,github:githubView,resume:resumeView,contact:contactView,achievements:achievementView,recycle:recycleView,settings:settingsView,leetcode:renderLeetCodeView})[id](win)}
function aboutView(){return `<div class="app-page"><div class="profile"><img class="avatar-large" src="/public/assets/harshit-avatar.webp" alt="${esc(profile.name)}"><div><p class="kicker">DEVELOPER PROFILE</p><h1>${esc(profile.name)}</h1><p>${esc(profile.role)}</p></div></div><p class="lede">${esc(profile.intro)}</p><div class="info-grid"><article><small>EDUCATION</small><strong>${esc(profile.education)}</strong></article><article><small>LOCATION</small><strong>${esc(profile.location)}</strong></article></div><h2>Relevant coursework</h2><div class="chips">${profile.coursework.map(x=>`<span>${esc(x)}</span>`).join('')}</div>${btn('projects','Explore projects →')} ${btn('contact','Get in touch →')}</div>`}
function pcView(){const folders=[['academics','Academic Records'],['projects','Projects'],['skills','Skills & Technologies'],['achievements','Achievements'],['resume','Resume'],['contact','Contact']];return `<div class="app-page"><p class="breadcrumb">This PC　›　Portfolio</p><h1>Browse portfolio</h1><p class="muted">Choose a folder to explore.</p><div class="folder-grid">${folders.map(([app,label])=>`<button class="folder" data-open="${app}"><span>${app==='academics'?'▥':'▰'}</span><strong>${label}</strong><small>Open folder　→</small></button>`).join('')}</div></div>`}
function projectCards(win){const q=(win.appState.query??'').toLowerCase(),sort=win.appState.sort??'name',category=win.appState.category??'all';return [...projects].filter(p=>(category==='all'||p.category===category)&&`${p.name} ${p.description} ${p.stack.join(' ')}`.toLowerCase().includes(q)).sort((a,b)=>a[sort].localeCompare(b[sort])).map(p=>`<article class="project-card"><p class="kicker">${esc(p.category).toUpperCase()}</p><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="chips">${p.stack.map(x=>`<span>${esc(x)}</span>`).join('')}</div><small>${esc(p.status)}</small><button class="text-button" data-project="${p.id}">Project details →</button></article>`).join('')||'<p class="empty">No projects match this search.</p>'}
function projectsView(win){const selected=projects.find(p=>p.id===win.appState.project);return `<div class="app-page"><p class="kicker">PROJECT EXPLORER</p><div class="page-heading"><h1>${selected?esc(selected.name):'Selected work'}</h1><div class="filters"><input data-project-search placeholder="Search projects" value="${esc(win.appState.query??'')}" aria-label="Search projects"><select data-project-category aria-label="Filter project category"><option value="all">All categories</option>${[...new Set(projects.map(p=>p.category))].map(c=>`<option value="${esc(c)}" ${win.appState.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select data-project-sort aria-label="Sort projects"><option value="name">Name A–Z</option><option value="category" ${win.appState.sort==='category'?'selected':''}>Category</option></select></div></div>${selected?`<button class="text-button" data-project-back>← All projects</button><p class="lede">${esc(selected.description)}</p><h2>Contribution</h2><p>${esc(selected.contribution)}</p><h2>Approach and features</h2><p>${esc(selected.challenge)}</p><h2>Stack</h2><div class="chips">${selected.stack.map(x=>`<span>${esc(x)}</span>`).join('')}</div>${selected.github||selected.demo?`<p class="muted">${selected.github?`<a href="${esc(selected.github)}">GitHub repository</a>`:''}${selected.github&&selected.demo?' · ':''}${selected.demo?`<a href="${esc(selected.demo)}">Live project</a>`:''}</p>`:''}`:`<div class="project-grid">${projectCards(win)}</div>`}</div>`}
function skillsView(win={appState:{}}){const selected=skills.flatMap(group=>group.items).find(([name])=>name===win.appState?.technology);return `<div class="app-page"><p class="kicker">SYSTEM INFORMATION</p><h1>Skills & Technologies</h1><p class="muted">Choose a technology to learn more.</p>${skills.map(g=>`<section class="skill-group"><h2>${esc(g.category)}</h2><div class="chips">${g.items.map(([name,note])=>`<button data-skill="${esc(name)}" data-note="${esc(note)}">${esc(name)}</button>`).join('')}</div></section>`).join('')}<div class="callout" id="skill-note">${selected?esc(selected[1]):'Choose a technology above.'}</div></div>`}
function githubView(){return `<div class="app-page"><p class="kicker">GITHUB PROFILE</p><h1>${esc(github.username)}</h1><p><a href="${esc(github.profileUrl)}" target="_blank" rel="noreferrer">Open GitHub profile →</a></p></div>`}
function resumeView(){return `<article class="resume-page"><div class="resume-tools"><span>RESUME</span><a href="${esc(profile.resumePath)}" download>Download PDF</a><button data-print>Print</button></div><h1>${esc(profile.name)}</h1><p>${esc(profile.location)} · ${esc(profile.phone)} · ${esc(profile.email)}</p><p>${esc(profile.role)}</p><p><a href="${esc(profile.linkedin)}">LinkedIn</a> · <a href="${esc(github.profileUrl)}" target="_blank" rel="noreferrer">GitHub</a> · <a href="${esc(profile.portfolio)}">Portfolio</a></p><hr><h2>Education</h2><p>${esc(profile.education)}</p><h2>Relevant coursework</h2><p>${profile.coursework.map(esc).join(' · ')}</p><h2>Projects</h2>${projects.map(p=>`<p><strong>${esc(p.name)}</strong> — ${esc(p.description)} <br><strong>Stack:</strong> ${p.stack.map(esc).join(', ')} <br>${esc(p.challenge)}</p>`).join('')}<h2>Technical skills</h2>${skills.map(g=>`<p><strong>${esc(g.category)}:</strong> ${g.items.map(x=>esc(x[0])).join(', ')}</p>`).join('')}</article>`}
function contactView(){const rows=[['Location',profile.location],['Phone',profile.phone],['Email',profile.email],['LinkedIn',profile.linkedin],['GitHub',github.profileUrl],['Portfolio',profile.portfolio]];return `<div class="app-page"><p class="kicker">CONTACT CENTER</p><h1>Say hello</h1><div class="contact-list">${rows.map(([name,value])=>`<div class="contact-row"><span>${esc(name)}</span><strong>${esc(value)}</strong>${name==='Email'?`<a href="mailto:${esc(value)}">Email</a>`:name==='Phone'?`<a href="tel:${esc(value.replaceAll(' ','').replaceAll('-',''))}">Call</a>`:name==='Location'?'':`<a href="${esc(value)}" target="_blank" rel="noreferrer">Open</a>`}</div>`).join('')}</div><form data-contact-form><label>Message<textarea required placeholder="Write a message to preview"></textarea></label><button class="primary">Preview message</button><p class="muted" data-contact-feedback aria-live="polite">Preview only. Your message will not be sent.</p></form></div>`}
function achievementView(win={appState:{}}){const items=achievements.items??[],selected=items.find(item=>String(item.id??item.title??item.name)===String(win.appState?.achievementId));return `<div class="app-page"><p class="kicker">EXPERIENCE & ACHIEVEMENTS</p><h1>Milestones</h1>${selected?`<article class="project-card"><h2>${esc(selected.title??selected.name)}</h2><p>${esc(selected.description??'')}</p><p>${esc(selected.organization??'')}${selected.date?` · ${esc(selected.date)}`:''}</p><button class="text-button" data-achievement-back>← All milestones</button></article>`:items.length?`<div class="project-grid">${items.map(item=>`<article class="project-card"><h2>${esc(item.title??item.name)}</h2><p>${esc(item.description??'')}</p><small>${esc(item.organization??'')}${item.date?` · ${esc(item.date)}`:''}</small><button class="text-button" data-achievement="${esc(item.id??item.title??item.name)}">Details →</button></article>`).join('')}</div>`:'<div class="empty">No milestones to display yet.</div>'}</div>`}
function recycleView(){return `<div class="app-page"><p class="kicker">RECYCLE BIN</p><h1>Nothing here</h1></div>`}
function settingsView(win){const prefs=win.preferences??{};return `<div class="app-page"><p class="kicker">PERSONALIZATION</p><h1>Settings</h1><div class="settings-list"><label>Wallpaper<select data-setting="wallpaper"><option value="crimson" ${prefs.wallpaper==='crimson'?'selected':''}>Crimson field</option><option value="night" ${prefs.wallpaper==='night'?'selected':''}>Night sky</option><option value="violet" ${prefs.wallpaper==='violet'?'selected':''}>Violet dusk</option></select></label><label>Accent<select data-setting="accent"><option value="red" ${prefs.accent==='red'?'selected':''}>Crimson</option><option value="gold" ${prefs.accent==='gold'?'selected':''}>Gold</option><option value="blue" ${prefs.accent==='blue'?'selected':''}>Blue</option></select></label><label class="check-setting">Reduce motion<input data-setting="reduceMotion" type="checkbox" ${prefs.reduceMotion?'checked':''}></label><label class="check-setting">Show desktop shortcuts<input data-setting="showIcons" type="checkbox" ${prefs.showIcons!==false?'checked':''}></label><label class="check-setting">Show lock screen on later visits<input data-setting="showLock" type="checkbox" ${prefs.showLock!==false?'checked':''}></label><button class="text-button" data-reset-layout>Reset desktop layout</button><button class="text-button" data-reset-demo>Reset app views</button></div></div>`}
function academicView(win){return renderAcademicView(win, {esc, semesters, subjects, suppliedCgpa, academicMetrics, gpaSeries, semesterSubjects, standoutSubjects, renderGpaChart});}
